  v_chunk jsonb := $batch161_12$[{"id":"footnote-28","kind":"paragraph","label":"28","text":"Сноска 28. При использовании в электронной промышленности применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-29","kind":"paragraph","label":"29","text":"Сноска 29. При использовании для плавки карбида кремния зеленого применяется поправочный коэффициент 1,3.","level":3},{"id":"footnote-30","kind":"paragraph","label":"30","text":"Сноска 30. При использовании для добычи кварца применяется поправочный коэффициент 0,6.","level":3},{"id":"footnote-31","kind":"paragraph","label":"31","text":"Сноска 31. При использовании в горно-химической промышленности, на строительном водопонижении и осушительных работах применяется поправочный коэффициент 0,5.","level":3},{"id":"footnote-32","kind":"paragraph","label":"32","text":"Сноска 32. При использовании в горно-химической промышленности, а также для химически активных жидкостей (раствор соли, коагулянта, извести, кислоты, щелочи), применяемых в энергетической отрасли, применяется поправочный коэффициент 0,6.","level":3},{"id":"footnote-33","kind":"paragraph","label":"33","text":"Сноска 33. При использовании для работы с химическими веществами применяется поправочный коэффициент 0,5.","level":3},{"id":"footnote-34","kind":"paragraph","label":"34","text":"Сноска 34. При использовании на угольных шахтах применяется поправочный коэффициент 1,7; при использовании на передвижных установках применяется поправочный коэффициент 0,7.","level":3},{"id":"footnote-35","kind":"paragraph","label":"35","text":"Сноска 35. При использовании в горно-химической промышленности применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-36","kind":"paragraph","label":"36","text":"Сноска 36. Применяется поправочный коэффициент 0,6.","level":3},{"id":"footnote-37","kind":"paragraph","label":"37","text":"Сноска 37. При использовании для работы с абразивными материалами в промышленности строительных материалов применяется поправочный коэффициент 0,7.","level":3},{"id":"footnote-38","kind":"paragraph","label":"38","text":"Сноска 38. При использовании на угольных разрезах применяется поправочный коэффициент 1,2.","level":3},{"id":"footnote-39","kind":"paragraph","label":"39","text":"Сноска 39. При использовании для поставок горно-химической продукции применяется поправочный коэффициент 0,8; при использовании на солебазах применяется поправочный коэффициент 0,6.","level":3},{"id":"footnote-40","kind":"paragraph","label":"40","text":"Сноска 40. При использовании для поставок горно-химической продукции применяется поправочный коэффициент 0,7; при использовании на солебазах применяется поправочный коэффициент 0,6.","level":3},{"id":"footnote-41","kind":"paragraph","label":"41","text":"Сноска 41. При использовании на угольных разрезах применяется поправочный коэффициент 0,7.","level":3},{"id":"footnote-42","kind":"paragraph","label":"42","text":"Сноска 42. При использовании на угольных разрезах применяется поправочный коэффициент 0,4.","level":3},{"id":"footnote-43","kind":"paragraph","label":"43","text":"Сноска 43. При использовании на угольных шахтах применяется поправочный коэффициент 1,3.","level":3},{"id":"footnote-44","kind":"paragraph","label":"44","text":"Сноска 44. При использовании для добычи угля применяется поправочный коэффициент 1,2.","level":3},{"id":"footnote-45","kind":"paragraph","label":"45","text":"Сноска 45. При использовании для работ по мелиорации (за исключением шифров 41808–41812) применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-46","kind":"paragraph","label":"46","text":"Сноска 46. При использовании для добычи угля применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-47","kind":"paragraph","label":"47","text":"Сноска 47. При использовании в условиях агрессивной среды и на солеотвалах применяется поправочный коэффициент 0,7.","level":3},{"id":"footnote-48","kind":"paragraph","label":"48","text":"Сноска 48. При использовании на открытых горных разработках, в гидротехническом, водохозяйственном и транспортном строительстве, а также при сооружении магистральных трубопроводов применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-49","kind":"paragraph","label":"49","text":"Сноска 49. При использовании для перевозок на расстояние свыше 10 км применяется поправочный коэффициент 0,6.","level":3},{"id":"footnote-50","kind":"paragraph","label":"50","text":"Сноска 50. При работе в две смены применяется поправочный коэффициент 0,5; при работе в три смены применяется поправочный коэффициент 0,4.","level":3},{"id":"footnote-51","kind":"paragraph","label":"51","text":"Сноска 51. Для передвижных, используемых в нефтегазовой промышленности применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-52","kind":"paragraph","label":"52","text":"Сноска 52. При использовании в нефтегазовой промышленности применяется поправочный коэффициент 0,7.","level":3},{"id":"footnote-53","kind":"paragraph","label":"53","text":"Сноска 53. При использовании для добычи угля, для измельчения калийной руды и каменной соли применяется поправочный коэффициент 0,6.","level":3},{"id":"footnote-54","kind":"paragraph","label":"54","text":"Сноска 54. При использовании для добычи угля применяется поправочный коэффициент 0,7.","level":3},{"id":"footnote-55","kind":"paragraph","label":"55","text":"Сноска 55. При использовании на алмазных фабриках применяется поправочный коэффициент 0,8; при использовании в условиях агрессивной среды в промышленности строительных материалов применяется поправочный коэффициент 0,7.","level":3},{"id":"footnote-56","kind":"paragraph","label":"56","text":"Сноска 56. При использовании для добычи угля применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-57","kind":"paragraph","label":"57","text":"Сноска 57. При использовании в горно-химической промышленности применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-58","kind":"paragraph","label":"58","text":"Сноска 58. При использовании для добычи кварца применяется поправочный коэффициент 0,6.","level":3},{"id":"footnote-59","kind":"paragraph","label":"59","text":"Сноска 59. При наличии двойной гидравлической раздвижности гидростоек применяется поправочный коэффициент 1,4.","level":3},{"id":"footnote-60","kind":"paragraph","label":"60","text":"Сноска 60. Применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-61","kind":"paragraph","label":"61","text":"Сноска 61. Применяется поправочный коэффициент 0,3.","level":3},{"id":"footnote-62","kind":"paragraph","label":"62","text":"Сноска 62. При использовании в титано-магниевой промышленности применяется поправочный коэффициент 1,4.","level":3},{"id":"footnote-63","kind":"paragraph","label":"63","text":"Сноска 63. При использовании в производстве смол на соляно-кислом катализаторе применяется поправочный коэффициент 2,5.","level":3},{"id":"footnote-64","kind":"paragraph","label":"64","text":"Сноска 64. Для осваиваемых с 1987 года при наличии регулируемого привода постоянного тока основных механизмов: применяется поправочный коэффициент 1,4.","level":3},{"id":"footnote-65","kind":"paragraph","label":"65","text":"Сноска 65. При использовании в условиях агрессивной среды применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-66","kind":"paragraph","label":"66","text":"Сноска 66. При использовании для вулканизации резинотехнических изделий применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-67","kind":"paragraph","label":"67","text":"Сноска 67. При использовании в производстве восстановления изношенных шин применяется поправочный коэффициент 0,8; при использовании в производстве резинотехнических изделий применяется поправочный коэффициент 0,7.","level":3},{"id":"footnote-68","kind":"paragraph","label":"68","text":"Сноска 68. Применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-69","kind":"paragraph","label":"69","text":"Сноска 69. При работе в две смены применяется поправочный коэффициент 0,6.","level":3},{"id":"footnote-70","kind":"paragraph","label":"70","text":"Сноска 70. При использовании в условиях агрессивной среды применяется поправочный коэффициент 0,7.","level":3},{"id":"footnote-71","kind":"paragraph","label":"71","text":"Сноска 71. Применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-72","kind":"paragraph","label":"72","text":"Сноска 72. При наличии деревянного, или композитного, или стеклопластикового корпуса применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-73","kind":"paragraph","label":"73","text":"Сноска 73. При наличии деревянного корпуса применяется поправочный коэффициент 0,5; при наличии композитного или стеклопластикового корпуса применяется поправочный коэффициент 0,6.","level":3},{"id":"footnote-74","kind":"paragraph","label":"74","text":"Сноска 74. При наличии деревянного, или композитного, или стеклопластикового корпуса применяется поправочный коэффициент 0,7.","level":3},{"id":"footnote-75","kind":"paragraph","label":"75","text":"Сноска 75. При использовании в условиях передвижения применяется поправочный коэффициент 0,7.","level":3},{"id":"footnote-76","kind":"paragraph","label":"76","text":"Сноска 76. При наличии данных об ином сроке службы (ресурсе) нормативный срок службы определяется на основании технических документов.","level":3},{"id":"footnote-77","kind":"paragraph","label":"77","text":"Сноска 77. При использовании учреждениями образования применяется поправочный коэффициент 1,3.","level":3},{"id":"footnote-78","kind":"paragraph","label":"78","text":"Сноска 78. При использовании учреждениями образования применяется поправочный коэффициент 1,3.","level":3},{"id":"footnote-79","kind":"paragraph","label":"79","text":"Сноска 79. При изготовлении основных сборочных единиц из стали углеродной обыкновенного качества применяется поправочный коэффициент 0,6.","level":3},{"id":"footnote-80","kind":"paragraph","label":"80","text":"Сноска 80. При использовании в шахтах и обогатительных цехах применяется поправочный коэффициент 0,5.","level":3},{"id":"footnote-81","kind":"paragraph","label":"81","text":"Сноска 81. При использовании в условиях агрессивной среды и для работы с абразивными материалами применяется поправочный коэффициент 0,6.","level":3},{"id":"footnote-82","kind":"paragraph","label":"82","text":"Сноска 82. При использовании в неблагоприятных внешних условиях и условиях интенсивной эксплуатации применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-83","kind":"paragraph","label":"83","text":"Сноска 83. В состав включаются: один монитор и более, один системный блок и более, мышь, коврик, клавиатура и другие комплектующие.","level":3},{"id":"footnote-84","kind":"paragraph","label":"84","text":"Сноска 84. Для шасси (ходовой части) применяются нормативные сроки службы, установленные для соответствующих видов транспортных средств.","level":3},{"id":"footnote-85","kind":"paragraph","label":"85","text":"Сноска 85. В зависимости от условий эксплуатации могут применяться поправочные коэффициенты:","level":3},{"id":"footnote-86","kind":"paragraph","label":"86","text":"Сноска 86. При использовании на лесозаготовках применяется поправочный коэффициент 0,5.","level":3},{"id":"footnote-87","kind":"paragraph","label":"87","text":"Сноска 87. При использовании на угольных разрезах применяется поправочный коэффициент 0,5.","level":3},{"id":"footnote-88","kind":"paragraph","label":"88","text":"Сноска 88. При использовании в карьерах применяется поправочный коэффициент 0,6; при использовании в черной металлургии применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-89","kind":"paragraph","label":"89","text":"Сноска 89. При использовании учреждениями образования применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-90","kind":"paragraph","label":"90","text":"Сноска 90. Для произведенных до 1989 года применяется поправочный коэффициент 0,5.","level":3},{"id":"footnote-91","kind":"paragraph","label":"91","text":"Сноска 91. При наличии данных об ином сроке службы (ресурсе) нормативный срок службы определяется на основании технических документов.","level":3},{"id":"footnote-92","kind":"paragraph","label":"92","text":"Сноска 92. При работе в полторы и две смены применяется поправочный коэффициент 0,7.","level":3},{"id":"footnote-93","kind":"paragraph","label":"93","text":"Сноска 93. При использовании на морском транспорте применяется поправочный коэффициент 0,7.","level":3},{"id":"footnote-94","kind":"paragraph","label":"94","text":"Сноска 94. Для обустройства устья скважин, восстановленных после ликвидации, применяется поправочный коэффициент 1,4.","level":3},{"id":"footnote-95","kind":"paragraph","label":"95","text":"Сноска 95. При использовании в горнодобывающей промышленности при добыче нефти и газа применяется поправочный коэффициент 0,5.","level":3},{"id":"footnote-96","kind":"paragraph","label":"96","text":"Сноска 96. Для скоростных пароводяных подогревателей с трубной системой из латуни, используемых в энергетической отрасли, применяется поправочный коэффициент 0,8.","level":3},{"id":"footnote-97","kind":"paragraph","label":"97","text":"Сноска 97. Для видеорегистраторов при использовании для выполнения оперативно-служебных задач в системе Министерства внутренних дел применяется поправочный коэффициент 0,8.","level":3}]$batch161_12$::jsonb;
BEGIN
  SELECT id, jsonb_array_length(structure)
  INTO v_document_id, v_structure_length
  FROM public.legal_documents
  WHERE external_id = 'w21124359'
  LIMIT 1;

  IF v_document_id IS NULL THEN
    RAISE EXCEPTION 'Resolution 161 staging document is missing';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.legal_documents
    WHERE id = v_document_id
      AND checksum = 'ac7e28c93b6b3d1f029cec22593157d1624f9de9c7ffee1a811bd60e743b5f4b'
      AND is_published
      AND jsonb_array_length(structure) = 2349
  ) THEN
    IF (
      SELECT count(*)
      FROM jsonb_array_elements(v_chunk) expected
      WHERE NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(
          (SELECT structure FROM public.legal_documents WHERE id = v_document_id)
        ) actual
        WHERE actual->>'id' = expected->>'id'
          AND actual = expected
      )
    ) <> 0 THEN
      RAISE EXCEPTION 'Resolution 161 finalized document differs from batch 12';
    END IF;
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.legal_documents
    WHERE id = v_document_id
      AND COALESCE(metadata #> '{resolution_161_import,applied_batches}', '[]'::jsonb)
        ? '12'
  ) THEN
    IF (
      SELECT count(*)
      FROM jsonb_array_elements(v_chunk) expected
      WHERE NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(
          (SELECT structure FROM public.legal_documents WHERE id = v_document_id)
        ) actual
        WHERE actual->>'id' = expected->>'id'
          AND actual = expected
      )
    ) <> 0 THEN
      RAISE EXCEPTION 'Resolution 161 batch 12 marker exists but content differs';
    END IF;
    RETURN;
  END IF;

  IF v_structure_length <> 2279 THEN
    RAISE EXCEPTION
      'Resolution 161 batch 12 expected structure length 2279, got %',
      v_structure_length;
  END IF;

  UPDATE public.legal_documents
  SET
    structure = structure || v_chunk,
    metadata = jsonb_set(
      metadata,
      '{resolution_161_import,applied_batches}',
      COALESCE(metadata #> '{resolution_161_import,applied_batches}', '[]'::jsonb)
        || to_jsonb('12'::text),
      true
    )
  WHERE id = v_document_id;

  IF jsonb_array_length(
    (SELECT structure FROM public.legal_documents WHERE id = v_document_id)
  ) <> 2349 THEN
    RAISE EXCEPTION 'Resolution 161 batch 12 read-back failed';
  END IF;
END
$migration$;
